std::wstring jsonString(const std::wstring& value){std::wstring out=L"\"";for(wchar_t c:value){if(c==L'\"'||c==L'\\'){out+=L'\\';out+=c;}else if(c<32){wchar_t code[7];swprintf(code,7,L"\\u%04x",(unsigned)c);out+=code;}else out+=c;}return out+L"\"";}
