 hr=profile2->ClearBrowsingDataAll(done);done->Release();profile2->Release();if(FAILED(hr)){clearingStorage=false;appStorage.notice=L"Stored data could not be cleared. Close other copies of the app and try again.";storageReply(L"storage-delete-all",false);}
