void storageCommand(const std::wstring& command){if(command!=L"storage-info"&&updater&&(updater->active()||updater->installing())){appStorage.notice=L"Wait for the update operation to finish before changing app data settings.";storageReply(command,false);return;}if(command==L"storage-info")storageReply(command);else if(command==L"storage-choose"){bool canceled=false;bool ok=appStorage.browse(windowHandle,canceled);if(!ok&&appStorage.notice.empty())appStorage.notice=L"The folder could not be selected.";storageReply(command,ok,canceled);}else if(command==L"storage-default")storageReply(command,appStorage.select(appStorage.defaultFolder));else if(command==L"storage-delete-all")clearStoredData();}
